import re

with open('./logs/memory_sync_errors.log', 'r') as f:
    log_lines = f.readlines()

# Categorize errors
error_types = {
    'version_conflict': [],
    'schema_mismatch': [],
    'pii_detected': [],
    'lock_timeout': [],
    'key_rotation_failed': [],
    'connection_pool_exhausted': [],
    'sync_latency_exceeded': []
}

for line in log_lines:
    if 'Version conflict' in line:
        error_types['version_conflict'].append(line.strip())
    elif 'Schema mismatch' in line:
        error_types['schema_mismatch'].append(line.strip())
    elif 'PII detected' in line:
        error_types['pii_detected'].append(line.strip())
    elif 'Timeout waiting for lock' in line:
        error_types['lock_timeout'].append(line.strip())
    elif 'Encryption key rotation failed' in line:
        error_types['key_rotation_failed'].append(line.strip())
    elif 'Connection pool exhausted' in line:
        error_types['connection_pool_exhausted'].append(line.strip())
    elif 'Sync latency exceeded' in line:
        error_types['sync_latency_exceeded'].append(line.strip())

print("Error Summary:")
print("="*60)
for err_type, errors in error_types.items():
    print(f"{err_type}: {len(errors)} occurrences")
    for err in errors[:3]:  # Show first 3
        print(f"  - {err[:100]}...")
    if len(errors) > 3:
        print(f"  ... and {len(errors)-3} more")
    print()
EOF
